"""Render a dated Linode guide and source hub; preserve existing observations, analytics and deployment policy."""
from pathlib import Path
from html import escape
from string import Template
import json
from config import ROOT

def publish_document(output, cfg, route, title, description, body, checked):
    url = cfg['base_url'] + route
    schema = json.dumps({'@context':'https://schema.org','@graph':[{'@type':'WebPage','name':title,'url':url,'dateModified':checked,'inLanguage':'en-US'}]})
    document = Template((ROOT/'templates/base.html').read_text(encoding='utf-8')).substitute(title=escape(title+' | '+cfg['brand']),description=escape(description),brand=escape(cfg['brand']),canonical='<link rel="canonical" href="'+escape(url)+'">' if cfg['base_url'] else '<meta name="robots" content="noindex">',schema=schema,url=escape(url),image=escape(cfg['base_url']+'/assets/og.png'),asset_version='guide',body=body,repository=escape(cfg['repository_url']))
    target=Path(output)/route.strip('/')/'index.html'
    target.parent.mkdir(parents=True,exist_ok=True)
    target.write_text(document,encoding='utf-8')
    return route,checked

def add_provider_link(output, route, label):
    hub=Path(output)/'providers/digitalocean/index.html'
    if not hub.exists(): return
    text=hub.read_text(encoding='utf-8')
    anchor='<a href="'+route+'">'+escape(label)+'</a>'
    marker='<p id="editorial-provider-links">'
    if marker in text:
        text=text.replace(marker,marker+anchor+' · ',1)
    else:
        text=text.replace('</main>','<section class="prose"><h2>Other provider source indexes</h2>'+marker+anchor+'</p></section></main>',1)
    hub.write_text(text,encoding='utf-8')

def publish_linode_articles(output,cfg):
    pages=[publish_document(output,cfg,'/pricing/linode/','Linode pricing: Shared CPU, transfer pools and retained volumes','North America official rates with separate backup prices, binary transfer units, annual budgets and stopped-service calculations.',BODY,CHECKED),publish_document(output,cfg,'/provider-guides/linode/','Linode / Akamai Cloud source index','Official source locations and billing scope for the Linode pricing guide.',HUB,CHECKED)]
    add_provider_link(output,'/provider-guides/linode/','Linode / Akamai Cloud')
    return pages

